async function xvondManagedRoute(companyId, connectionKey) {
  const base = String($env.XVOND_WORKFLOW_REGISTRY_URL || '').replace(/\/$/, '');
  const secret = String($env.XVOND_WORKFLOW_REGISTRY_SECRET || '');
  if (!base || !secret || !companyId || !connectionKey) return null;
  try {
    const response = await fetch(
      base + '/v1/routes/' + encodeURIComponent(String(companyId)) + '/' + encodeURIComponent(String(connectionKey)),
      {headers:{'X-Xvond-Registry-Secret':secret}}
    );
    if (!response.ok) return null;
    const payload = await response.json().catch(() => null);
    const row = payload?.route;
    if (!row) return null;
    return {
      ...(row.provider_config || {}),
      provider_secret:String(row.provider_secret || ''),
      provider_type:String(row.provider_type || ''),
      provider_url:String(row.provider_url || ''),
      company_id:Number(row.company_id || 0),
      agent_id:Number(row.agent_id || 0),
      channel_id:Number(row.channel_id || 0),
      connection_key:String(row.connection_key || connectionKey)
    };
  } catch (_error) {
    return null;
  }
}
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;
const supplied = String(headers['x-xvond-channel-secret'] || headers['X-Xvond-Channel-Secret'] || '');
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '').trim();
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const companyId = Number(body.company_id || 0);
const connectionKey = String(data.connection_key || '').trim();
const routeKey = `${companyId}:${connectionKey}`;
const route = await xvondManagedRoute(companyId, connectionKey);
if (!route || String(route.provider_secret || '').length < 32 || String(route.outbound_secret || '').length < 32 || !route.outbound_url) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Custom channel route is not configured',error_code:'provider_not_configured',data:null}}];
}
if (!supplied || supplied !== String(route.provider_secret)) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unauthorized custom channel provider request',error_code:'unauthorized',data:null}}];
}
if (action !== 'channel.send') {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Unsupported custom channel provider action',error_code:'unsupported_action',data:null}}];
}
let outboundUrl;
try {
  const parsed = new URL(String(route.outbound_url || ''));
  if (parsed.protocol !== 'https:' || parsed.username || parsed.password) throw new Error('invalid');
  if (['localhost','127.0.0.1','0.0.0.0','::1'].includes(parsed.hostname.toLowerCase())) throw new Error('invalid');
  outboundUrl = parsed.toString();
} catch (_error) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Custom outbound URL is invalid',error_code:'provider_not_configured',data:null}}];
}
const externalContactId = String(data.external_contact_id || '').trim();
const message = String(data.message || '').trim();
const idempotencyKey = String(data.idempotency_key || '').trim();
if (!requestId || !externalContactId || !message || !idempotencyKey) {
  return [{json:{success:false,_dispatch:'reject',request_id:requestId,action,error:'Invalid custom channel send contract',error_code:'invalid_contract',data:null}}];
}
return [{json:{
  success:true,
  _dispatch:'custom_send',
  request_id:requestId,
  action,
  route_key:routeKey,
  outbound_url:outboundUrl,
  outbound_secret:String(route.outbound_secret),
  external_contact_id:externalContactId,
  message,
  idempotency_key:idempotencyKey
}}];

const response = $input.first().json;
const request = $('Validate Custom Send').first().json;
if (!response || response.success !== true || !String(response.provider_message_id || '').trim()) {
  return [{json:{success:false,request_id:request.request_id,action:request.action,error:'Custom channel endpoint did not confirm delivery',error_code:'provider_rejected',data:null}}];
}
return [{json:{
  success:true,
  request_id:request.request_id,
  action:request.action,
  data:{provider_message_id:String(response.provider_message_id).trim()},
  error:null
}}];
